import{_ as r,a0 as a,w as s,s as i,ao as l,I as p,x as e,a1 as u,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux有问必答：如何删除Ubuntu上不再使用的旧内核 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何删除Ubuntu上不再使用的旧内核 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何删除Ubuntu上不再使用的旧内核 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何删除Ubuntu上不再使用的旧内核 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150914 Linux FAQs with Answers--How to remove unused old kernel images on Ubuntu","title":"Linux有问必答：如何删除Ubuntu上不再使用的旧内核","tag":"201509","desc":""},"relativePath":"201509/20150914 Linux FAQs with Answers--How to remove unused old kernel images on Ubuntu.md","filePath":"[post].md"}'),d={name:"201509/20150914 Linux FAQs with Answers--How to remove unused old kernel images on Ubuntu.md"};function m(g,t,x,b,f,U){const n=a("Link");return s(),i("div",null,[t[13]||(t[13]=l(`<h1 id="linux有问必答-如何删除ubuntu上不再使用的旧内核" tabindex="-1">Linux有问必答：如何删除Ubuntu上不再使用的旧内核 <a class="header-anchor" href="#linux有问必答-如何删除ubuntu上不再使用的旧内核" aria-label="Permalink to “Linux有问必答：如何删除Ubuntu上不再使用的旧内核”">​</a></h1><blockquote><p><strong>提问</strong>：过去我已经在我的Ubuntu上升级了几次内核。现在我想要删除这些旧的内核镜像来节省我的磁盘空间。如何用最简单的方法删除Ubuntu上先前版本的内核？</p></blockquote><p>在Ubuntu上，有几个方法来升级内核。在Ubuntu桌面中，软件更新允许你每天检查并更新到最新的内核上。在Ubuntu服务器上，最为重要的安全更新项目之一就是 unattended-upgrades 软件包会自动更新内核。然而，你也可以手动用apt-get或者aptitude命令来更新。</p><p>随着时间的流逝，持续的内核更新会在系统中积聚大量的不再使用的内核，浪费你的磁盘空间。每个内核镜像和其相关联的模块/头文件会占用200-400MB的磁盘空间，因此由不再使用的内核而浪费的磁盘空间会快速地增加。</p><p><img src="https://farm1.staticflickr.com/636/21352725115_29ae7aab5f_c.jpg" alt=""></p><p>GRUB管理器为每个旧内核都维护了一个GRUB入口，以备你想要使用它们。</p><p><img src="https://farm6.staticflickr.com/5803/21164866468_07760fc23c_z.jpg" alt=""></p><p>作为磁盘清理的一部分，如果你不再使用这些，你可以考虑清理掉这些镜像。</p><h3 id="如何清理旧内核镜像" tabindex="-1">如何清理旧内核镜像 <a class="header-anchor" href="#如何清理旧内核镜像" aria-label="Permalink to “如何清理旧内核镜像”">​</a></h3><p>在删除旧内核之前，记住最好留有2个最近的内核（最新的和上一个版本），以防主要的版本出错。现在就让我们看看如何在Ubuntu上清理旧内核。</p><p>在Ubuntu内核镜像包含了以下的包。</p><ul><li><code>linux-image-&lt;VERSION-NUMBER&gt;</code>: 内核镜像</li><li><code>linux-image-extra-&lt;VERSION-NUMBER&gt;</code>: 额外的内核模块</li><li><code>linux-headers-&lt;VERSION-NUMBER&gt;</code>: 内核头文件</li></ul><p>首先检查系统中安装的内核镜像。</p><pre><code>$ dpkg --list | grep linux-image
$ dpkg --list | grep linux-headers
</code></pre><p>在列出的内核镜像中，你可以移除一个特定的版本（比如3.19.0-15）。</p><pre><code>$ sudo apt-get purge linux-image-3.19.0-15
$ sudo apt-get purge linux-headers-3.19.0-15
</code></pre><p>上面的命令会删除内核镜像和它相关联的内核模块和头文件。</p><p>注意如果你还没有升级内核那么删除旧内核会自动触发安装新内核。这样在删除旧内核之后，GRUB配置会自动升级来移除GRUB菜单中相关GRUB入口。</p><p>如果你有很多没用的内核，你可以用shell表达式来一次性地删除多个内核。注意这个括号表达式只在bash或者兼容的shell中才有效。</p><pre><code>$ sudo apt-get purge linux-image-3.19.0-{18,20,21,25}
$ sudo apt-get purge linux-headers-3.19.0-{18,20,21,25}
</code></pre><p><img src="https://farm6.staticflickr.com/5619/21352725355_39cc4fc2d0_c.jpg" alt=""></p><p>上面的命令会删除4个内核镜像：3.19.0-18、3.19.0-20、3.19.0-21 和 3.19.0-25。</p><p>如果GRUB配置由于任何原因在删除旧内核后没有正确升级，你可以尝试手动用update-grub2命令来更新配置。</p><pre><code>$ sudo update-grub2
</code></pre><p>现在就重启来验证GRUB菜单是否已经正确清理了。</p><p><img src="https://farm1.staticflickr.com/593/20731623163_cccfeac854_z.jpg" alt=""></p><hr>`,27)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),u(n,{href:"http://ask.xmodulo.com/remove-kernel-images-ubuntu.html"},{default:o(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/remove-kernel-images-ubuntu.html",-1)])]),_:1})]),p("p",null,[t[5]||(t[5]=e("作者：",-1)),u(n,{href:"http://ask.xmodulo.com/author/nanni"},{default:o(()=>[...t[2]||(t[2]=[e("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),u(n,{href:"https://github.com/geekpi"},{default:o(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),u(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[10]||(t[10]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创编译，",-1)),u(n,{href:"https://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const h=r(d,[["render",m]]);export{_ as __pageData,h as default};
